pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newOwner) public {
        // keep domain wide: allow any address including zero
        // The property: calling owner() returns the current owner stored in contract; specifically we will set owner to address(0)
        // Use setCaller flow: onlyOwner functions exist; setCaller requires onlyOwner, so must be called by deployer (owner)
        // First, ensure we are the owner and can set caller: setCaller expects onlyOwner; deployer (this) is owner by constructor

        // set cfo to an arbitrary nonzero to exercise some mutation paths (not necessary but harmless)
        c.setCaller(address(0x1234));

        // Now transfer ownership to the fuzzed newOwner via transferOwnership if we are owner
        // transferOwnership is onlyOwner, so this contract (deployer) can call it
        c.transferOwnership(newOwner);

        // Now call the owner() getter and assert it equals the publicly returned owner
        // The reference implementation always returns the stored _owner; the mutant changes how owner() reads when _owner == address(0)
        address reportedOwner = c.owner();

        // Single assertion: the reported owner must equal the value we passed to transferOwnership
        // On the correct contract this holds for all inputs; on the mutant it will fail for some input (notably when newOwner == address(0) if mutant behaved differently)
        assertTrue(reportedOwner == newOwner);
    }
}

