pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameter: an address to transfer ownership to (may be zero address).
    // General rule: owner() returns the stored owner value for every input. The mutant
    // changes behavior when the stored owner is address(0) and may return address(0)
    // in that case (observable difference). We fuzz the newOwner to allow the fuzzer
    // to pick address(0) and other addresses.
    function testFuzz_property(address newOwner) public {
        // allow any address (including zero) as candidate
        // perform the transferOwnership from the current owner (setUp deployer is msg.sender and owner)
        // we must call setCaller as owner; setUp deployer (this contract) is owner so call directly
        // If newOwner is address(0) the reference contract's transferOwnership will revert (per reference)
        // because reference requires newOwner != address(0). To create a scenario where owner can become address(0),
        // we instead call renounceOwnership when newOwner == address(0) so owner becomes zero in the reference.

        if (newOwner == address(0)) {
            // renounceOwnership will set owner to zero in the reference implementation
            c.renounceOwnership();
        } else {
            // transfer to fuzzed non-zero owner
            c.transferOwnership(newOwner);
        }

        // Now read owner via the public getter. Both reference and mutant complete the call.
        // The rule: the getter returns the actual stored owner value. We assert that calling owner()
        // returns either the same address we set (newOwner) or address(0) if we renounced.
        address observed = c.owner();

        // Exactly one assertion: the observed owner must equal newOwner when newOwner != address(0),
        // or must equal address(0) when we renounced (newOwner == address(0)). This property holds
        // for the reference for all inputs, but the mutant may change behavior when owner is zero.
        if (newOwner == address(0)) {
            assertTrue(observed == address(0));
        } else {
            assertTrue(observed == newOwner);
        }
    }
}

