import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz a candidate newOwner. The general rule: after calling transferOwnership(newOwner)
    // (from the current owner), c.owner() must return the stored owner value (i.e. newOwner).
    // The mutant returns address(0) whenever internal _owner is zero regardless; thus fuzzing
    // newOwner including address(0) will find divergence.
    function testFuzz_property(address newOwner) public {
        // keep domain wide but ensure caller is the current owner (deployer) who is owner initially
        // no vm.assume needed; address(this) (deployer) is owner by constructor.

        // perform the ownership transfer from the owner (address(this)) to fuzzed newOwner
        // call through as the owner
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // Read observed owner via public getter. Use try/catch to be robust (getter is view and shouldn't revert)
        bool ok;
        address observed;
        try c.owner() returns (address o) {
            ok = true;
            observed = o;
        } catch {
            ok = false;
            observed = address(0);
        }

        // The canonical expected value is exactly the newOwner we set. The reference satisfies
        // that for every newOwner; the mutant will differ when newOwner == address(0) if it
        // introduced a conditional branch changing returned value (it will still return address(0)
        // but that matches expected), however the mutant's behavior differs in cases where
        // internal storage could be zero while expected non-zero — to ensure detection we assert
        // equality of observed to newOwner (this passes on reference for all inputs and will fail
        // on the mutant for inputs where the mutant's branch produces a different return).
        assertTrue(ok && observed == newOwner);
    }
}

