pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameter is an address candidate for newOwner. We will deploy a helper that REVERTS
    // when any call is made to it. We then attempt to transferOwnership to that helper address.
    // Reference contract requires newOwner != address(0) and thus will still attempt to set the
    // owner; if the helper can cause a transfer to fail in reference but mutant allowed zero or
    // other problematic addresses, the behavior will differ. We use a reverting helper to model an
    // adversarial external party; the fuzzer still supplies the candidate address which we check
    // against helper.
    function testFuzz_property(address newOwnerCandidate) public {
        // Keep domain wide but non-equal to zero to allow both cases; still allow zero so fuzzer can try it.
        // Deploy a helper that always reverts on any call.
        Reverter r = new Reverter();

        // Decide which target to use: either the fuzzed address (if non-zero) or the reverting helper.
        // We want the fuzzer to still explore addresses, so we do not constrain newOwnerCandidate.
        address target = newOwnerCandidate;
        if (target == address(0)) {
            // prefer the reverter to exercise an external failing callee
            target = address(r);
        }

        // Only the owner (deployer) can call transferOwnership. We are that owner in setUp().
        bool ok;
        try c.transferOwnership(target) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule to assert: If the reference is correct, then transferring ownership to the
        // special reverter contract address MUST revert (ok == false). The mutant that removed the
        // require may allow the call to succeed for some inputs, so the assertion will fail on mutant.
        // We assert that calling transferOwnership with the reverting helper address reverts.
        // Note: we ensure target was set to the helper when fuzzed candidate was zero; otherwise the
        // fuzzer-provided address might be an EOA and the call would succeed in both, so we only
        // assert the behavior for the helper address scenario which the fuzzer can still trigger
        // by passing address(0).
        if (newOwnerCandidate == address(0)) {
            // When fuzzer supplies address(0) we used the reverting helper as target, so expect revert
            assertTrue(!ok);
        } else {
            // When fuzzer supplies non-zero, we cannot guarantee revert (both may succeed), so assert true trivially
            // to keep property universal for reference; however per rules we must have exactly one assertTrue
            // across the test — already used above in the zero case. To satisfy the single-assert requirement
            // and still be valid for all inputs, we structure so that the only assert is in the branch the
            // fuzzer can trigger to distinguish. For non-zero, we simply perform no assertion.
            // (no-op)
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

