pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: an address that will act as a relayer contract and a boolean
    // We only need one fuzzed parameter (address relayer). The fuzzer will search addresses
    function testFuzz_property(address relayer) public {
        // Keep relayer non-zero and not equal to address(this) to be a meaningful external contract
        vm.assume(relayer != address(0));
        vm.assume(relayer != address(this));

        // Deploy a tiny relayer contract from an EOA account (use addr as deployer)
        // We need an EOA to deploy the Relayer so tx.origin during relayed call is the deployer EOA
        address deployer = address(uint160(uint256(keccak256(abi.encodePacked(relayer, block.timestamp)))));
        vm.deal(deployer, 1 ether);
        vm.startPrank(deployer);
        Relayer r = new Relayer();
        vm.stopPrank();

        // sanity: the owner is the test contract (set in C constructor via _msgSender())
        address ownerBefore = c.owner();
        // The test contract is the owner; ensure ownerBefore equals address(this)
        // (constructed with new C(address(this)) in setUp())
        // Now attempt to call transferOwnership via the relayer contract such that
        // tx.origin == deployer, and msg.sender in C will be the relayer contract address r.
        // For the correct contract, only msg.sender == owner should succeed, so this forwarded call should fail.

        // Build calldata for transferOwnership(address)
        bytes memory payload = abi.encodeWithSignature("transferOwnership(address)", address(0x1234));

        // Make the relayer call C.transferOwnership(...) on behalf of deployer (tx.origin==deployer)
        vm.startPrank(address(r));
        // r will perform a low-level call to c with the given data
        bool ok;
        try r.forwardCall(address(c), payload) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // After the forwarded call, read the owner
        address ownerAfter = c.owner();

        // ASSERTION: In the correct reference, a forwarded call where msg.sender != owner must NOT change ownership.
        // Thus ownerAfter == ownerBefore should hold for all relayer addresses.
        // The mutant that checks tx.origin instead of msg.sender will allow the forwarded call to succeed
        // when tx.origin equals the deployer (which is not the owner), causing ownerAfter != ownerBefore for some inputs.
        assertTrue(ownerAfter == ownerBefore);
    }
}

// Minimal relayer contract: forwards arbitrary calldata to target using a call from its own address
contract Relayer {
    function forwardCall(address target, bytes calldata data) external returns (bool) {
        (bool success, ) = target.call(data);
        return success;
    }
}
